<script setup lang="ts">import{Head,Link}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';interface Customer{id:number;first_name:string|null;last_name:string|null;email:string|null;phone:string|null;state:string|null;verified_email:boolean;orders_count:number;total_spent:string;created_at_shopify:string|null;updated_at_shopify:string|null;synced_at:string|null}const props=defineProps<{customer:Customer}>();const fullName=()=>`${props.customer.first_name??''} ${props.customer.last_name??''}`.trim()||'未命名客户';const stateLabel=(value:string|null)=>({enabled:'启用',disabled:'禁用',invited:'已邀请',declined:'已拒绝'}[value??'']??value??'未知');const money=(value:string)=>Number(value).toFixed(2);</script>
<template><Head :title="fullName()"/><AppLayout :breadcrumbs="[{label:'业务中心'},{label:'客户管理',href:'/customers'},{label:fullName()}]"><div class="mx-auto max-w-5xl space-y-6"><Link href="/customers" class="text-sm font-semibold text-slate-500">← 返回客户列表</Link><header><p class="text-sm font-semibold text-emerald-700">Shopify 客户</p><h1 class="mt-1 text-3xl font-semibold text-slate-950">{{fullName()}}</h1><p class="mt-2 text-sm text-slate-500">{{customer.email||'未填写邮箱'}}</p></header><section class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div v-for="item in [['邮箱',customer.email||'—'],['电话',customer.phone||'—'],['账号状态',stateLabel(customer.state)],['邮箱验证',customer.verified_email?'已验证':'未验证'],['订单数量',String(customer.orders_count)],['累计消费',money(customer.total_spent)]]" :key="String(item[0])" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wider text-slate-400">{{item[0]}}</p><p class="mt-2 break-all font-semibold text-slate-900">{{item[1]}}</p></div></section></div></AppLayout></template>
